<template><view class="login"><view class="brand"><view class="mark">安</view><view><view class="eyebrow">徐州中燃能源有限公司</view><view class="name">徐燃安巡</view></view></view><view class="panel"><view class="title">登录工作台</view><view class="copy">演示环境可选择账号身份；生产环境将由公司统一账号服务校验。</view><view class="label">用户名</view><input v-model="username" placeholder="请输入用户名"/><view class="label">密码</view><input v-model="password" password placeholder="至少 10 位，含字母、数字和特殊字符"/><view class="error" v-if="error">{{error}}</view><view class="demo">演示身份</view><view class="roles"><view v-for="role in allRoles" :key="role.id" class="role" :class="{active:selected===role.id}" @click="selected=role.id">{{role.roleName}}</view></view><button @click="login">登录</button></view></view></template>
<script setup>import {ref} from 'vue';import {allRoles,demoStore} from '../../stores/demo';const username=ref('demo'),password=ref('Demo@2026'),selected=ref('admin'),error=ref('');function login(){if(!username.value||!password.value){error.value='请输入用户名和密码';return}demoStore.setRole(selected.value);uni.switchTab({url:'/pages/index/index'})}</script>
<style lang="scss" scoped>.login{min-height:100dvh;box-sizing:border-box;padding:72rpx 32rpx;background:radial-gradient(circle at 10% 0%,#f7e9ed,transparent 32%),#f5f2ef}.brand{display:flex;align-items:center;gap:18rpx;max-width:940px;margin:auto}.mark{width:72rpx;height:72rpx;display:flex;align-items:center;justify-content:center;border-radius:18rpx 18rpx 18rpx 4rpx;background:#211d1d;color:#fff;font-size:35rpx;font-weight:700}.eyebrow{font-size:20rpx;letter-spacing:2rpx;color:#756c6b}.name{font-size:40rpx;font-weight:760}.panel{max-width:620px;margin:66rpx auto;background:#fffcfa;padding:42rpx;border-radius:26rpx;box-shadow:0 24rpx 70rpx rgba(79,49,51,.12)}.title{font-size:42rpx;font-weight:750}.copy{font-size:23rpx;color:#756c6b;line-height:1.65;margin:12rpx 0 28rpx}.label,.demo{font-size:23rpx;font-weight:650;margin:22rpx 0 10rpx}input{background:#f5f2ef;padding:21rpx;border-radius:12rpx;font-size:25rpx}.roles{display:flex;flex-wrap:wrap;gap:12rpx}.role{background:#eee8e5;color:#756c6b;padding:10rpx 14rpx;border-radius:10rpx;font-size:21rpx}.role.active{background:#f8e8ed;color:#9f2349}button{margin-top:30rpx;background:#211d1d;color:#fff;border-radius:13rpx;font-size:28rpx}.error{margin-top:14rpx;color:#b62e2b;font-size:22rpx}</style>
